<?php $title='Invoices';require __DIR__.'/../layouts/header.php';?><div class="pagehead"><div><h1>Invoices & Receivables</h1><p>Track invoice status, paid amounts and outstanding balances.</p></div><a class="primary" href="<?=route('invoice.create')?>">+ New Invoice</a></div><div class="panel table-wrap"><table><thead><tr><th>Invoice</th><th>Client</th><th>Status</th><th>Total</th><th>Paid</th><th>Balance</th><th>Due</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><a href="<?=route('invoice.view',['id'=>$r['id']])?>"><?=e($r['invoice_number'])?></a></td><td><?=e($r['full_name'])?></td><td><span class="badge"><?=e($r['status'])?></span></td><td><?=money((float)$r['grand_total'])?></td><td><?=money((float)$r['total_paid'])?></td><td><?=money((float)$r['balance'])?></td><td><?=e($r['due_date'])?></td></tr><?php endforeach;?></tbody></table></div><?php require __DIR__.'/../layouts/footer.php';?>
